// P3.5 golden replays (ARCHITECTURE §10.4): 20 deterministic deals per base
// game, generated by Tools/make-game-replays.sh (Packages/RulesetKit
// GoldenGen executable) from the live corpus and committed under
// Tests/Fixtures/Replays/<game>-NN.json.
//
// A golden file records the resolved ruleset hash, the seed, the full action
// log (seat + intent + state version), and the SHA-256 of the terminal
// GameState JSON. The test re-resolves the live ruleset, replays the logged
// actions through a freshly built engine, and hashes the terminal state; any
// divergence — engine, ruleset, or platform — fails here, which is what makes
// the cross-platform hash-match acceptance criterion checkable (the same
// fixtures run again under `make test-replays-ios` in CI).
//
// Replay file format `parlor.replay/1`: intents as
// "play:<raw>"/"call:<text>"/"pass:<raw,raw>"/"discard:<raw,raw>"/
// "drawFrom:<zone>"/"meld:<raw,raw>"/"choose:<text>"/"claim:<n>"/
// "acceptClaim:<bool>"/"cut:<n>"/"count:<n>"/"confirm"; hashes as lowercase
// hex. Mirrors Packages/RulesEngine/Tests/ReplayTests.swift.

import CardModel
import Foundation
@_spi(HostOnly) import RulesEngine
import RulesetKit
@_spi(HostOnly) import RulesetKit
import Testing

struct GoldenReplay: Codable {
    let format: String
    let rulesetHash: String
    let seed: UInt64
    let seatCount: Int
    let actions: [ActionLine]
    let finalStateHash: String

    struct ActionLine: Codable {
        let seat: Int
        let intent: String
        let version: UInt64
    }
}

@Suite("RulesetKit — Golden replays (§10.4, P3.5)")
struct GameReplayTests {

    static func fixturesDirectory() -> URL {
        // Anchor on this test source file so fixtures resolve regardless of
        // the process working directory (macOS swift test cwd, iOS simulator
        // app sandbox, or an xcodebuild invocation elsewhere).
        // <package>/Tests/RulesetKitTests/… → <package>/Tests/Fixtures/Replays
        let packageRoot = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()  // RulesetKitTests
            .deletingLastPathComponent()  // Tests
            .deletingLastPathComponent()  // package root
        return
            packageRoot
            .appendingPathComponent("Tests", isDirectory: true)
            .appendingPathComponent("Fixtures", isDirectory: true)
            .appendingPathComponent("Replays", isDirectory: true)
    }

    static func hex(_ data: Data) -> String {
        data.map { String(format: "%02x", $0) }.joined()
    }

    static func parseIntent(_ text: String) throws -> ActionIntent {
        func cardList(_ raw: Substring) throws -> [CardID] {
            raw.isEmpty
                ? []
                : try raw.split(separator: ",").map { part -> CardID in
                    guard let n = UInt16(part) else { throw ReplayFormatError.badIntent(text) }
                    return CardID(n)
                }
        }
        guard let colon = text.firstIndex(of: ":") else {
            if text == "confirm" { return .confirm }
            throw ReplayFormatError.badIntent(text)
        }
        let kind = String(text[..<colon])
        let rest = text[text.index(after: colon)...]
        switch kind {
        case "play":
            guard let raw = UInt16(rest) else { throw ReplayFormatError.badIntent(text) }
            return .play(CardID(raw))
        case "call": return .call(String(rest))
        case "pass": return .pass(try cardList(rest))
        case "discard": return .discard(try cardList(rest))
        case "drawFrom": return .drawFrom(String(rest))
        case "meld": return .meld(try cardList(rest))
        case "choose": return .choose(String(rest))
        case "claim":
            guard let n = Int(rest) else { throw ReplayFormatError.badIntent(text) }
            return .claim(n)
        case "acceptClaim": return .acceptClaim(rest == "true")
        case "cut":
            guard let d = Int(rest) else { throw ReplayFormatError.badIntent(text) }
            return .cut(depth: d)
        case "count":
            guard let p = Int(rest) else { throw ReplayFormatError.badIntent(text) }
            return .count(points: p)
        case "confirm": return .confirm
        default: throw ReplayFormatError.badIntent(text)
        }
    }

    enum ReplayFormatError: Error { case badIntent(String) }

    static func decode(_ data: Data) throws -> (GoldenReplay, Replay) {
        let golden = try JSONDecoder().decode(GoldenReplay.self, from: data)
        var actions: [LoggedAction] = []
        for line in golden.actions {
            let intent = try parseIntent(line.intent)
            actions.append(LoggedAction(seat: Seat(line.seat), intent: intent, version: line.version))
        }
        let replay = Replay(
            rulesetHash: Data(), seed: golden.seed, seatCount: golden.seatCount, actions: actions)
        return (golden, replay)
    }

    /// The four base games, 20 golden files each (80 total).
    static let games = ["hearts", "euchre", "contract-bridge-rubber", "cribbage-six-card"]

    @Test(arguments: GameReplayTests.games)
    func twentyGoldenReplaysMatch(game: String) throws {
        let resolved = try ConformanceRulesets.resolved(game: GameReplayTests.baseName(game))
        let engine = try EngineBuilder.build(from: resolved)
        let directory = GameReplayTests.fixturesDirectory()
        let files = try FileManager.default.contentsOfDirectory(at: directory, includingPropertiesForKeys: nil)
            .filter { $0.lastPathComponent.hasPrefix("\(game)-") && $0.pathExtension == "json" }
            .sorted { $0.lastPathComponent < $1.lastPathComponent }
        #expect(
            files.count == 20,
            "\(game): expected 20 golden replays, found \(files.count)")

        var mismatched = 0
        for file in files {
            let (golden, replay) = try GameReplayTests.decode(try Data(contentsOf: file))
            #expect(golden.format == "parlor.replay/1", "\(file.lastPathComponent): bad format")
            // The generator pins each deal to the resolved ruleset's canonical
            // hash ("identifies a game everywhere"). A mismatch means the
            // ruleset or resolution changed without regenerating the goldens.
            #expect(
                golden.rulesetHash == resolved.hash,
                "\(file.lastPathComponent): ruleset hash mismatch — regenerate goldens")
            let finalState = try engine.replay(replay)
            let hash = GameReplayTests.hex(Engine.finalStateHash(finalState))
            if hash != golden.finalStateHash { mismatched += 1 }
            #expect(
                hash == golden.finalStateHash,
                "\(file.lastPathComponent): final-state hash mismatch")
        }
        #expect(mismatched == 0, "\(game): \(mismatched) golden replay(s) diverged")
    }

    /// The generator's seed list is fixed (see Tools/make-game-replays.sh);
    /// this suite pins the four base games and the 20-per-game count.
    @Test func fixedSeedListDocumented() {
        #expect(GameReplayTests.games.count == 4)
    }

    /// "hearts" → "hearts.standard", "contract-bridge-rubber" →
    /// "contract-bridge.rubber", etc.
    static func baseName(_ slug: String) -> String {
        if slug.hasPrefix("contract-bridge-rubber") { return "contract-bridge.rubber" }
        if slug.hasPrefix("cribbage-six-card") { return "cribbage.six-card" }
        return "\(slug).standard"
    }
}
